/bin/bash -lc "ruby -ryaml -rjson -e '
nodes = {}
Dir[\"hgraph/nodes/*.md\"].each do |path|
  text = File.read(path)
  next unless text.start_with?(\"---\\n\")
  _, head, body = text.split(/"'^---'"\\s*"'$'"\\n?/, 3)
  meta = YAML.safe_load(head, aliases: true) || {}
  nodes[File.basename(path, \".md\")] = [meta, body.to_s]
end
edges = JSON.parse(File.read(\"/tmp/ajcr-edges.json\")).select { |e| e[\"type\"] == \"formalizes\" }
by_target = Hash.new { |h,k| h[k] = [] }
edges.each do |e|
  sm, sb = nodes.fetch(e[\"source\"])
  tag = sb[/\\\\provenancetag\\{(REFERENCE|ADAPTED|CUSTOM)\\}/, 1]
  by_target[e[\"target\"]] << [e[\"source\"], tag, sm[\"label\"]]
end
conflicts = by_target.select { |_t, xs| xs.map { |x| x[1] }.compact.uniq.length > 1 }
missing = by_target.select { |_t, xs| xs.any? { |x| x[1].nil? } }
priv = by_target.count { |t,_| nodes.fetch(t)[0][\"private\"] }
files = by_target.map { |t,_| nodes.fetch(t)[0][\"file\"] }.compact.uniq
puts \"formalizes=#{edges.length} targets=#{by_target.length} files=#{files.length} private=#{priv} conflicts=#{conflicts.length} missing_source_tag=#{missing.length}\"
conflicts.first(20).each { |t,xs| p [nodes[t][0][\"decl\"], xs] }
'"

